Rainbow tables are precomputed lookup tables designed to speed up hash lookups by reusing known values instead of recalculating them for every entry. Here's the standard approach:

```javascript
// Generate rainbow table (simple sequential lookup)
class RainbowTable {
  constructor(size) {
    this.size = size;
    this.hashTable = new Array(size);
    for(let i=0;i<size;i++) this.hashTable[i] = new Array(this.size);
  }

  get(passwordHash) {
    const hash = this.hash(passwordHash);
    const idx = hash & 0xFFFF;
    const val = this.hashTable[idx];
    if(!val) return false;
    return val[0];
  }

  hash(password) {
    return password.toString().split('').reduce((prev, char, i) => {
      return prev + char.charCodeAt(0) + (char.charCodeAt(i) || 0) * 0x1000000 + (i % 2 === 0 ? 0 : 1);
    }, 0);
  }
}

// Example usage (simplified)
